function render(){stopWordAudio();renderCoursePicker();const route=location.hash.slice(1)||'home';document.querySelector('#nav').innerHTML=sections.map(([id,icon,name])=>`<a href="#${id}" class="${id===route?'active':''}" ${id===route?'aria-current="page"':''}>${icon} &nbsp; ${name}</a>`).join('');if(state.level!==2){app.innerHTML=intro('HSK'+state.level,'Chưa có bài học','Tài liệu cho cấp độ này chưa được thêm. Chọn HSK2 → Lesson 1 để bắt đầu học.');}else{(pages[route]||pages.home)();}window.scrollTo(0,0)}
const pages={home(){app.innerHTML=`${intro('MỖI NGÀY MỘT CHÚT TIẾN BỘ','Chào bạn, cùng học nhé.','Một góc nhỏ để học, luyện tập và tự tin hơn với tiếng Trung.')}<section class="hero"><div><div class="eyebrow">HSK2 · LESSON 1</div><h1>你在听什么？</h1><p>Nǐ zài tīng shénme? · Bạn đang nghe gì?</p><a class="btn" href="#words">Bắt đầu học &nbsp; ↗</a></div><div class="hero-mark" aria-hidden="true">听</div></section><div class="stats"><div class="stat"><small>TỪ ĐÃ NHỚ</small><strong>${state.known.length}<small> / 22</small></strong><small>Từng từ, từng bước</small></div><div class="stat"><small>NGỮ PHÁP</small><strong>02</strong><small>Mẫu câu trọng tâm</small></div><div class="stat"><small>ĐIỂM LUYỆN TẬP</small><strong>${state.score===undefined?'—':state.score+'/6'}</strong><small>${state.score===undefined?'Sẵn sàng thử sức':'Kết quả lần gần nhất'}</small></div></div><div class="section-head"><h2>Hôm nay bạn muốn học gì?</h2><span class="pill">Bài 01</span></div><div class="grid">${[['words','字','Từ vựng','22 mục từ · Flashcard · Nghe & gõ'],['grammar','✧','Ngữ pháp','Đang làm gì · Vừa… vừa…'],['dialogue','☷','Hội thoại','Sở thích, âm nhạc & cuối tuần'],['practice','✓','Luyện tập','Điền từ · Chọn đáp án'],['listening','♫','Luyện nghe','4 file bạn đã cung cấp'],['writing','✎','Luyện viết','Bảng viết tay · Tự luyện chữ']].map(([id,icon,title,desc])=>`<a href="#${id}" class="card card-link"><span class="icon">${icon}</span><h3>${title} <span style="float:right">↗</span></h3><p>${desc}</p></a>`).join('')}</div><h3>Tiến độ từ vựng <span class="pill">${pct()}%</span></h3><div class="progress"><i style="width:${pct()}%"></i></div>`},words(){app.innerHTML=intro('TỪ VỰNG · BÀI 01','Gặp từ mới, nhớ lâu hơn.','Chạm “Đã nhớ” để theo dõi tiến độ. Trong sách, 在／正在／正 thuộc cùng một mục; ở đây tách ra để ôn.')+`<div class="toolbar"><input id="search" placeholder="Tìm chữ Hán, pinyin hoặc nghĩa…" aria-label="Tìm từ"><button class="btn secondary" id="flashBtn">Ôn flashcard ↗</button><button class="btn" id="dictationBtn">♫ Nghe & gõ chữ Hán</button></div><div id="wordlist" class="grid"></div>`;drawWords('');document.querySelector('#search').oninput=e=>drawWords(e.target.value);document.querySelector('#flashBtn').onclick=flash;document.querySelector('#dictationBtn').onclick=()=>startDictation()},grammar(){app.innerHTML=intro('NGỮ PHÁP · BÀI 01','Nói về điều đang diễn ra.','Hai mẫu câu trọng tâm, giải thích bằng tiếng Việt.')+`<article class="card grammar"><h2>01 · Hành động đang diễn ra</h2><div class="pattern">Chủ ngữ + 在／正在／正 + động từ</div><p>Dùng để nói một hành động đang xảy ra. Có thể thêm 呢 ở cuối câu.</p><p class="han" style="font-size:23px">你在做什么？ — 我在听音乐（呢）。</p><p class="sub">Bạn đang làm gì? — Mình đang nghe nhạc.</p><p>Ví dụ: 他正在喝咖啡。— Anh ấy đang uống cà phê.</p></article><article class="card grammar"><h2>02 · Vừa… vừa…</h2><div class="pattern">Chủ ngữ + 一边 + việc A + 一边 + việc B</div><p>Diễn tả hai hoạt động diễn ra cùng lúc với cùng một chủ thể.</p><p class="han" style="font-size:23px">她一边唱歌，一边跳舞。</p><p class="sub">Cô ấy vừa hát vừa nhảy.</p><p>我喜欢一边吃饭，一边看书。<br>Tôi thích vừa ăn vừa đọc sách.</p></article><a href="#practice" class="btn">Luyện mẫu câu →</a>`},dialogue(){app.innerHTML=intro('HỘI THOẠI · BÀI 01','Bạn thích làm gì?','Đoạn hội thoại trong giáo trình. Có thể ẩn pinyin để luyện đọc chữ Hán.')+`<button class="btn secondary" id="pinyin">${showPinyin?'Ẩn':'Hiện'} pinyin</button>`+dialogues.map(([title,lines])=>`<h2>${title}</h2>${lines.map(([name,han,py,vi])=>`<div class="dialogue"><small>${name}</small><p class="han">${han}</p>${showPinyin?`<p class="pinyin">${py}</p>`:''}<p>${vi}</p></div>`).join('')}`).join('');document.querySelector('#pinyin').onclick=()=>{showPinyin=!showPinyin;pages.dialogue()}},practice(){app.innerHTML=intro('LUYỆN TẬP · BÀI 01','Thử sức một chút nhé.','Câu hỏi ôn tập biên soạn từ từ vựng và mẫu câu của bài. Chọn đáp án rồi nộp để xem giải thích.')+`<form id="quiz">${quiz.map((q,i)=>`<fieldset class="card question"><legend>Câu ${i+1}</legend><h3>${q[0]}</h3>${q[1].map((v,j)=>`<label><input required type="radio" name="q${i}" value="${j}"> ${v}</label>`).join('')}<div id="f${i}"></div></fieldset>`).join('')}<button class="btn" type="submit">Nộp bài & xem kết quả</button><p id="result" aria-live="polite"></p></form>`;document.querySelector('#quiz').onsubmit=e=>{e.preventDefault();const form=new FormData(e.target);let score=0;quiz.forEach((q,i)=>{const ok=Number(form.get('q'+i))===q[2];if(ok)score++;document.querySelector('#f'+i).innerHTML=`<div class="feedback ${ok?'good':'bad'}">${ok?'✓ Chính xác':'↺ Đáp án: '+q[1][q[2]]}<br>${q[3]}</div>`});state.score=score;save();document.querySelector('#result').textContent=`Bạn đúng ${score}/6 câu. Có thể đổi đáp án và làm lại để ôn tập.`}},listening(){app.innerHTML=intro('LUYỆN NGHE · BÀI 01','Lắng nghe theo nhịp của bạn.','Chọn tốc độ, nghe lại và ghi chú những từ bạn nhận ra.')+`<div class="notice">Đây là 4 file từ thư mục BTNC bạn cung cấp. Chưa xác minh chúng tương ứng với mã 01-1, 01-2, 01-3 trong giáo trình; vì vậy phần này chưa chấm câu hỏi nghe.</div>`+['Q2B1.mp3','Q2B1.NC1.MP3','Q2B1.NC2.MP3','Q2B1.NC3.MP3'].map((f,i)=>`<article class="card grammar"><h3>0${i+1} · ${f}</h3><audio controls preload="none" src="audio/${f}">Trình duyệt chưa hỗ trợ phát âm thanh.</audio><label>Tốc độ <select aria-label="Tốc độ ${f}" data-audio="${i}"><option value="0.75">0.75×</option><option value="1" selected>1×</option><option value="1.25">1.25×</option></select></label></article>`).join('')+`<label for="notes">Ghi chú của bạn</label><textarea id="notes" rows="5" style="width:100%;padding:15px;margin-top:12px;border:1px solid #dce1d6;border-radius:12px;font:inherit" placeholder="Những từ mình nghe được…"></textarea>`;document.querySelector('#notes').value=state.notes||'';document.querySelector('#notes').oninput=e=>{state.notes=e.target.value;save()};document.querySelectorAll('select').forEach(s=>s.onchange=()=>document.querySelectorAll('audio')[s.dataset.audio].playbackRate=Number(s.value));document.querySelectorAll('audio').forEach(a=>a.onplay=()=>document.querySelectorAll('audio').forEach(b=>{if(a!==b)b.pause()}))},writing(){app.innerHTML=intro('LUYỆN VIẾT · BÀI 01','Viết chậm, nhớ sâu.','Bảng tự luyện chữ bằng chuột hoặc ngón tay. Chưa chấm nét và chưa mô phỏng thứ tự nét.')+`<div class="toolbar"><label>Chữ mẫu <select id="model">${['听','音','乐','唱','歌','球','舞','周','末'].map(w=>`<option>${w}</option>`).join('')}</select></label><button class="btn secondary" id="clear">Xóa bảng</button></div><div class="card" style="max-width:460px"><div class="han" id="modelchar" style="text-align:center;font-size:72px;margin-bottom:15px">听</div><canvas id="writing" width="400" height="400" aria-label="Bảng luyện viết chữ Hán"></canvas><p class="sub">Nhìn chữ mẫu phía trên và viết vào ô. Bảng viết không tự lưu.</p></div><p class="sub">Vở tập viết PDF bạn cung cấp chưa được đối chiếu với bài này.</p>`;const c=document.querySelector('canvas'),ctx=c.getContext('2d');let drawing=false;ctx.lineWidth=7;ctx.lineCap='round';ctx.lineJoin='round';ctx.strokeStyle='#174d43';function point(e){const r=c.getBoundingClientRect();return [(e.clientX-r.left)*400/r.width,(e.clientY-r.top)*400/r.height]}c.onpointerdown=e=>{drawing=true;c.setPointerCapture(e.pointerId);ctx.beginPath();ctx.moveTo(...point(e))};c.onpointermove=e=>{if(drawing){ctx.lineTo(...point(e));ctx.stroke()}};c.onpointerup=c.onpointercancel=()=>drawing=false;document.querySelector('#clear').onclick=()=>ctx.clearRect(0,0,400,400);document.querySelector('#model').onchange=e=>{document.querySelector('#modelchar').textContent=e.target.value;ctx.clearRect(0,0,400,400)}}};
function drawWords(query){const normalized=s=>s.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'');const matches=words.map((w,i)=>({w,i})).filter(({w})=>normalized(w.join(' ')).includes(normalized(query)));document.querySelector('#wordlist').innerHTML=matches.length?matches.map(({w,i})=>`<article class="card word"><div class="han">${w[0]}</div><div class="pinyin">${w[1]}</div><p class="meaning">${w[2]}</p><p class="example">${w[3]}</p><button class="btn ${state.known.includes(i)?'':'secondary'}" data-known="${i}">${state.known.includes(i)?'✓ Đã nhớ':'Đánh dấu đã nhớ'}</button></article>`).join(''):'<p class="empty">Chưa tìm thấy từ phù hợp.</p>';document.querySelectorAll('[data-known]').forEach(b=>b.onclick=()=>{const i=Number(b.dataset.known);state.known=state.known.includes(i)?state.known.filter(v=>v!==i):[...state.known,i];save();drawWords(query)})}
function flash(){const w=words[idx];app.innerHTML=intro('FLASHCARD',`Thẻ ${idx+1} / ${words.length}`,'Chạm thẻ để xem nghĩa và ví dụ.')+`<div class="flash"><button class="face" aria-label="Lật thẻ"><div class="han">${w[0]}</div><p class="pinyin">${w[1]}</p>${flip?`<p>${w[2]}</p><p>${w[3]}</p>`:'<p class="sub">Chạm để lật thẻ ↻</p>'}</button><div class="toolbar"><button id="prev" class="btn secondary">← Trước</button><button id="remember" class="btn">${state.known.includes(idx)?'✓ Đã nhớ':'Mình đã nhớ'}</button><button id="next" class="btn secondary">Tiếp →</button></div><button id="list" class="btn secondary">Về danh sách từ</button></div>`;document.querySelector('.face').onclick=()=>{flip=!flip;flash()};document.querySelector('#prev').onclick=()=>{idx=(idx+21)%22;flip=false;flash()};document.querySelector('#next').onclick=()=>{idx=(idx+1)%22;flip=false;flash()};document.querySelector('#remember').onclick=()=>{if(!state.known.includes(idx))state.known.push(idx);save();flash()};document.querySelector('#list').onclick=pages.words}
const quiz=[['我 ___ 听音乐。',['在','一起','下次'],0,'在 đặt trước động từ để diễn tả hành động đang diễn ra.'],['她一边唱歌，___ 跳舞。',['只','一边','下个'],1,'一边……一边…… nối hai hoạt động cùng diễn ra.'],['“平时” có nghĩa là gì?',['Lần sau','Cuối tuần','Thường ngày'],2,'平时 (píngshí) chỉ lúc bình thường, thường ngày.'],['“Tôi chỉ thích nghe nhạc.”',['我只喜欢听音乐。','我一起喜欢听音乐。','我下次喜欢听音乐。'],0,'只 (zhǐ) có nghĩa là “chỉ”.'],['我们下个周末 ___ 看吧！',['正在','一起','只'],1,'一起 nghĩa là “cùng nhau”: Cuối tuần tới chúng ta cùng xem nhé!'],['“打篮球” nghĩa là gì?',['Xem phim','Chơi bóng rổ','Nhảy đường phố'],1,'打篮球: chơi bóng rổ; 看电影: xem phim; 跳街舞: nhảy đường phố.']];
