const courses={1:[],2:[{id:'1',title:'Lesson 1 — 你在听什么？'}],3:[],4:[]};
state.level=[1,2,3,4].includes(state.level)?state.level:2;
function renderCoursePicker(){
 const lessons=courses[state.level];
 document.querySelectorAll('[data-level]').forEach(button=>{
  const selected=Number(button.dataset.level)===state.level;
  button.setAttribute('aria-pressed',String(selected));button.classList.toggle('selected',selected);
  button.onclick=()=>{state.level=Number(button.dataset.level);save();render();};
 });
 const select=document.querySelector('#lesson-select');
 select.innerHTML=lessons.length?lessons.map(lesson=>'<option value="'+lesson.id+'">'+lesson.title+'</option>').join(''):'<option value="">Chưa có lesson</option>';
 select.disabled=lessons.length===0;select.onchange=()=>{location.hash='home';render();};
 document.querySelector('#course-book').textContent=state.level===2?'Quyển 2':'';
 document.querySelector('footer').textContent=state.level===2?'HSK2 · Lesson 1 · Tiến độ được lưu trên trình duyệt này.':'HSK'+state.level+' · Chưa có tài liệu.';
}
window.addEventListener('hashchange',render);render();
